// Validate and normalize input payload from FastAPI
const body = $input.item.json.body || $input.item.json;
if (!body.message || !body.conversation_id) {
  throw new Error('Invalid input: message and conversation_id are required.');
}

return {
  json: {
    conversation_id: body.conversation_id,
    user_id: body.user_id,
    user_role: body.user_role || 'student',
    department_id: body.department_id || null,
    message: body.message.trim(),
    retrieved_passages: body.retrieved_passages || []
  }
};

const searchResult = $input.item.json;
const prevData = $('Validate Input').first().json;

let passages = [];
if (Array.isArray(searchResult.passages) && searchResult.passages.length > 0) {
  passages = searchResult.passages;
} else if (Array.isArray(prevData.retrieved_passages) && prevData.retrieved_passages.length > 0) {
  passages = prevData.retrieved_passages;
}

let contextText = '';
const sourceCitations = [];

passages.forEach((p, idx) => {
  contextText += `\n[Document #${idx + 1}: ${p.title || p.document_title || 'Study Material'}, Page ${p.page_number || p.page || 1}]\n${p.content}\n`;
  sourceCitations.push({
    document_id: p.document_id,
    title: p.title || p.document_title || 'Study Material',
    page: p.page_number || p.page || 1
  });
});

return {
  json: {
    conversation_id: prevData.conversation_id,
    user_id: prevData.user_id,
    message: prevData.message,
    contextText: contextText.trim(),
    sourceCitations: sourceCitations,
    hasSources: sourceCitations.length > 0
  }
};

const aiOutput = $input.item.json.output || $input.item.json.text || '';
const contextData = $('Prepare Context').first().json;

return {
  json: {
    conversation_id: contextData.conversation_id,
    answer: aiOutput,
    sources: contextData.sourceCitations || [],
    status: 'completed'
  }
};
